mapper.update:
UPDATE mes_wo_material
SET issued_qty = issued_qty + #{qty}, supplement_qty = supplement_qty + #{qty}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT x.id AS wo_material_id, x.wo_id, o.wo_no, o.status AS wo_status, o.qty AS wo_qty, o.plan_start, o.material_id AS product_id, p.code AS product_code, p.name AS product_name, x.material_id, m.code AS material_code, m.name AS material_name, m.spec, m.unit, m.serial_enabled, x.unit_qty, x.required_qty, x.supplement_qty, x.issued_qty, GREATEST(x.required_qty + x.supplement_qty - x.issued_qty, 0) + COALESCE((SELECT SUM(si.qty - si.issued_qty) FROM mes_wo_supplement_item si JOIN mes_wo_supplement s ON s.id = si.supp_id WHERE s.wo_id = x.wo_id AND s.status = 'APPROVED' AND si.material_id = x.material_id), 0) AS to_issue_qty FROM mes_wo_material x JOIN mes_work_order o ON o.id = x.wo_id JOIN wms_material m ON m.id = x.material_id JOIN wms_material p ON p.id = o.material_id WHERE o.status IN #{s}
AND x.material_id IN #{id}
ORDER BY CASE WHEN o.status = 'DRAFT' THEN 1 ELSE 0 END, CASE WHEN o.plan_start IS NULL THEN 1 ELSE 0 END, o.plan_start, o.id, x.id

SELECT x.material_id AS "materialId", SUM(GREATEST(x.required_qty + x.supplement_qty - x.issued_qty, 0)) AS "qty"
FROM mes_wo_material x
JOIN mes_work_order o ON o.id = x.wo_id
WHERE o.status IN #{s}
  AND x.material_id IN #{id}
GROUP BY x.material_id
